record.field:
{
    "type": "object",
    "properties": {
        "snippet_keys": {
            "type": "array",
            "description": "List of snippet keys to retrieve",
            "items": {
                "type": "string",
                "description": "The unique key of the snippet to retrieve (e.g., 's_snippet_key')"
            }
        }
    },
    "required": ["snippet_keys"]
}

{
    "type": "object",
    "properties": {
        "elements": {
            "type": "array",
            "description": "Selected website elements and the additional computed CSS properties required for each one",
            "items": {
                "type": "object",
                "properties": {
                    "id": {
                        "type": "string",
                        "description": "The selected element's id from the current page context"
                    },
                    "properties": {
                        "type": "array",
                        "description": "Computed CSS property names to retrieve in kebab-case",
                        "items": {
                            "type": "string"
                        }
                    }
                },
                "required": ["id", "properties"]
            }
        }
    },
    "required": ["elements"]
}

{
    "type": "object",
    "properties": {
        "pattern": {
            "type": "string",
            "description": "A regular expression to match routes against (e.g. 'cart|checkout', 'snippet.*filter')"
        }
    },
    "required": ["pattern"]
}

{
    "type": "object",
    "properties": {
        "scope": {
            "type": "string",
            "description": "How far the user allowed it: 'chat' for this conversation only, 'website' to turn the website setting on",
            "enum": ["chat", "website"]
        }
    },
    "required": ["scope"]
}

{
    "type": "object",
    "properties": {
        "paths": {
            "type": "array",
            "description": "List of backend route paths to get documentation for",
            "items": {
                "type": "string",
                "description": "An exact path returned by the \"Search Backend Routes\" tool (e.g. '/shop/cart/add')"
            }
        }
    },
    "required": ["paths"]
}

{
    "type": "object",
    "properties": {
        "query": {
            "type": "string",
            "description": "The search query to find images on Unsplash (e.g., 'nature', 'technology')"
        }
    },
    "required": ["query"]
}

{
    "type": "object",
    "properties": {
        "attachments_ids": {
            "type": "array",
            "description": "List of attachment IDs to create (e.g., [567, 568])",
            "items": {
                "type": "number",
                "description": "The unique ID of the attachment to create (e.g., 567)"
            }
        }
    },
    "required": ["attachments_ids"]
}

{
    "type": "object",
    "properties": {
        "urls": {
            "type": "array",
            "description": "One or more webpages to scrape, 10 at most",
            "items": {
                "type": "object",
                "description": "A webpage to scrape, with the assets needed from it",
                "properties": {
                    "url": {
                        "type": "string",
                        "description": "The webpage URL to scrape"
                    },
                    "fetch_images": {
                        "type": "boolean",
                        "description": "Return the source URLs of the images of this page, with their size and position. Ask for them when you want to reuse this page's images."
                    },
                    "take_screenshot": {
                        "type": "boolean",
                        "description": "Attach a screenshot of this page. Ask for it when you need to see the layout, colors or style of this page, not when you only need its text."
                    }
                },
                "required": ["url", "fetch_images", "take_screenshot"]
            }
        }
    },
    "required": ["urls"]
}

{
    "type": "object",
    "properties": {
        "page_name": {
            "type": "string",
            "description": "Name of the new page. It is also used to generate the page URL."
        },
        "add_to_menu": {
            "type": "boolean",
            "description": "Whether to add the new page to the website's main menu. Defaults to false."
        },
        "leave_empty": {
            "type": "boolean",
            "description": "Set to true only if the user explicitly asked for a blank page with no content. When true, do not call \"Apply HTML to Page\" for this page afterwards. Defaults to false."
        }
    },
    "required": ["page_name"]
}

{
    "type": "object",
    "properties": {
        "actions": {
            "type": "array",
            "description": "List of actions to apply to the page.",
            "items": {
                "type": "object",
                "description": "Insert or replace HTML markup, optionally including its JavaScript.",
                "properties": {
                    "zone": {
                        "type": "string",
                        "enum": ["main", "footer"],
                        "description": "The zone of the page to apply the action to (main or footer)"
                    },
                    "mode": {
                        "type": "string",
                        "enum": ["after", "before", "replace"],
                        "description": "after: adds new HTML after the queried element; before: adds new HTML before the queried element; replace: replaces the queried element with the new HTML"
                    },
                    "selector": {
                        "type": "string",
                        "description": "A CSS selector to target elements in the specified zone. Leave empty to target the whole zone (only for replace mode)"
                    },
                    "content": {
                        "type": "string",
                        "description": "The full outer HTML to insert."
                    }
                },
                "required": ["zone", "mode", "content"]
            }
        }
    },
    "required": ["actions"]
}

{
    "type": "object",
    "properties": {
        "css_content": {
            "type": "string",
            "description": "The SCSS rules to write in user_custom_rules.scss"
        }
    },
    "required": ["css_content"]
}

{
    "type": "object",
    "properties": {
        "operations": {
            "type": "array",
            "description": "List of menu operations, applied in order",
            "items": {
                "type": "object",
                "properties": {
                    "type": {
                        "type": "string",
                        "enum": ["create", "update", "delete"],
                        "description": "The kind of operation to perform"
                    },
                    "menu_id": {
                        "type": "number",
                        "description": "ID of the menu item to edit (required for update and delete)"
                    },
                    "name": {
                        "type": "string",
                        "description": "The label of the menu item (required for create)"
                    },
                    "url": {
                        "type": "string",
                        "description": "The target of the menu item: a page path (e.g. '/contactus'), an external URL (e.g. 'https://example.com'), an email address (e.g. 'info@example.com'), '#' for a parent item that only opens a dropdown, or a page path followed by '#anchor-id' to scroll to a section anchor on that page (e.g. '/about-us#our-team')"
                    },
                    "new_window": {
                        "type": "boolean",
                        "description": "Whether the link opens in a new browser tab"
                    },
                    "sequence": {
                        "type": "number",
                        "description": "Position of the item among its siblings (lower comes first)"
                    },
                    "parent_menu_id": {
                        "type": "number",
                        "description": "ID of the menu item to nest this item under. Use 0 to place the item at the top level of the menu"
                    },
                    "temp_id": {
                        "type": "string",
                        "description": "Temporary identifier for a created item (e.g. 'new_1') so later operations in the same call can nest items under it with parent_temp_id"
                    },
                    "parent_temp_id": {
                        "type": "string",
                        "description": "temp_id of an item created by a previous operation in the same call to nest this item under"
                    }
                },
                "required": ["type"]
            }
        }
    },
    "required": ["operations"]
}

{
    "type": "object",
    "properties": {
        "palette": {
            "type": "object",
            "description": "The five brand colours (and optional per-preset overrides). Omit to keep the current palette.",
            "properties": {
                "o_color_1": {"type": "string", "description": "Primary brand colour, 6-digit hex (e.g. '#1A547A')"},
                "o_color_2": {"type": "string", "description": "Secondary accent, 6-digit hex"},
                "o_color_3": {"type": "string", "description": "Soft / muted background tone, 6-digit hex"},
                "o_color_4": {"type": "string", "description": "Lightest tone, 6-digit hex (often near-white)"},
                "o_color_5": {"type": "string", "description": "Darkest tone, 6-digit hex (often near-black)"},
                "cc_presets": {
                    "type": "array",
                    "description": "Optional per-preset overrides. Omit any preset or slot to keep its default.",
                    "items": {
                        "type": "object",
                        "properties": {
                            "index": {"type": "integer", "description": "Which o_ccN preset to override; integer 1..5"},
                            "bg": {"type": "string", "description": "Section background, 6-digit hex"},
                            "text": {"type": "string", "description": "Body text colour, 6-digit hex"},
                            "headings": {"type": "string", "description": "Heading colour, 6-digit hex"},
                            "link": {"type": "string", "description": "Link colour, 6-digit hex"},
                            "btn-primary": {"type": "string", "description": "Primary button background, 6-digit hex"},
                            "btn-secondary": {"type": "string", "description": "Secondary button background, 6-digit hex"}
                        },
                        "required": ["index"]
                    }
                }
            },
            "required": ["o_color_1", "o_color_2", "o_color_3", "o_color_4", "o_color_5"]
        },
        "typography": {
            "type": "object",
            "description": "Font pairing. Omit to keep the current fonts. Use only names from the allowed font catalog in your instructions.",
            "properties": {
                "heading_font": {"type": "string", "description": "Heading / display font name (e.g. 'Playfair Display')"},
                "body_font": {"type": "string", "description": "Body / paragraph font name (e.g. 'Inter')"},
                "button_font": {"type": "string", "description": "Optional button font name; defaults to the body font"}
            },
            "required": ["heading_font", "body_font"]
        },
        "design": {
            "type": "object",
            "description": "Corner and shadow language. Omit to keep the current values.",
            "properties": {
                "corners": {"type": "string", "enum": ["sharp", "subtle", "rounded", "pill"], "description": "Site-wide button/input rounding"},
                "shadow": {"type": "string", "enum": ["none", "flat", "soft", "dramatic"], "description": "Site-wide shadow depth language"}
            },
            "required": []
        }
    },
    "required": []
}

{
    "type": "object",
    "properties": {
        "url": {
            "type": "string",
            "description": "URL of the page to read (e.g. '/about-us'). Omit for the homepage."
        }
    },
    "required": []
}
